// VALIDAR PEDIDO — o Terminal manda o PDF da FIN em base64, com a lead e o banco.
// O Airtable so aceita anexos ate 5 MB por esta via; "JVBER" e o inicio de "%PDF" em base64.
const b = $input.first().json.body || {};
const base64 = String(b.ficheiro || '').replace(/^data:[^,]*,/, '');
const banco = String(b.banco || '').trim();
let erro = null;
if (!b.lead_id || !banco) erro = 'Falta a lead ou o banco.';
else if (!base64) erro = 'Não veio nenhum ficheiro.';
else if (base64.length * 3 / 4 > 5 * 1024 * 1024) erro = 'O PDF tem mais de 5 MB — o Airtable não aceita.';
else if (!base64.startsWith('JVBER')) erro = 'O ficheiro não é um PDF.';
const agora = new Date().toISOString();
return [{ json: { erro, lead_id: b.lead_id, banco, base64,
  nome: `FIN ${banco} ${agora.slice(0, 10)}.pdf`, carregada_em: agora } }];

// MONTAR RESUMO — se o Gemini falhou (429 por quota, etc.) o PDF ja ficou guardado
// e a proposta regista o erro; o comercial volta a carregar a FIN mais tarde.
const r = $input.first().json;
let resumo = null, erro = null;
try {
  const txt = r.candidates[0].content.parts.map(p => p.text || '').join('');
  resumo = JSON.parse(txt);
} catch (e) { erro = r.candidates ? 'ia_resposta_invalida' : 'ia_sem_resposta'; }

// A resposta do upload traz os anexos do campo (chave = id do campo, nao o nome).
// O nosso e o ultimo com o nome que lhe demos.
const up = $('Guardar PDF (Airtable)').first().json;
const anexos = Object.values(up.fields || {}).find(Array.isArray) || [];
const nome = $('Validar pedido').first().json.nome;
const anexo = [...anexos].reverse().find(a => a.filename === nome) || anexos[anexos.length - 1] || {};
return [{ json: { resumo, erro, anexo_id: anexo.id || null, anexo_url: anexo.url || null } }];

// JUNTAR A PROPOSTA — le o propostas_banco do Airtable agora (nao o que o Terminal
// tinha) e so mexe na entrada deste banco. Banco que ainda nao estava na lista entra como pedido.
const v = $('Validar pedido').first().json;
const m = $('Montar resumo').first().json;
const lead = $input.first().json;
const f = lead.fields || lead;
let lista = [];
try {
  const raw = f.propostas_banco;
  const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
  if (Array.isArray(parsed)) lista = parsed;
} catch (e) {}
const fin = { anexo_id: m.anexo_id, nome: v.nome, carregada_em: v.carregada_em, resumo: m.resumo, erro: m.erro };
const i = lista.findIndex(p => String(p.banco || '').toLowerCase() === v.banco.toLowerCase());
if (i >= 0) lista[i] = { ...lista[i], fin };
else lista.push({ banco: v.banco, estado: 'pedido', fin });
return [{ json: { id: v.lead_id, propostas_banco: JSON.stringify(lista), lista } }];
